// 文件系统服务: 统一封装 Tauri FS 插件, 供 UI 文件树/资源浏览与 LSP 反向请求共用。

import { mkdir, readDir, readFile, readTextFile, remove, rename, stat, writeTextFile } from '@tauri-apps/plugin-fs';

export interface FsEntry {
  name: string;
  isDirectory: boolean;
}

export interface ExistsResult {
  exists: boolean;
  isDirectory: boolean;
}

export const fs = {
  async exists(path: string): Promise<ExistsResult> {
    try {
      const info = await stat(path);
      return { exists: true, isDirectory: info.isDirectory };
    } catch {
      return { exists: false, isDirectory: false };
    }
  },

  async readDir(path: string): Promise<FsEntry[]> {
    const entries = await readDir(path);
    return entries.map((e) => ({ name: e.name, isDirectory: e.isDirectory }));
  },

  async readText(path: string): Promise<string> {
    return readTextFile(path);
  },

  async readBytes(path: string): Promise<Uint8Array> {
    return readFile(path);
  },

  async writeText(path: string, content: string): Promise<void> {
    await writeTextFile(path, content);
  },

  async mkdir(path: string): Promise<void> {
    await mkdir(path, { recursive: true });
  },

  async remove(path: string, recursive = false): Promise<void> {
    await remove(path, { recursive });
  },

  async rename(from: string, to: string): Promise<void> {
    await rename(from, to);
  },
};
